dtsPropsFor.DeltaStat:
label: string;
/** Seconds vs. the reference;
negative = faster (green), positive = slower (red), null = "—". */ d: number | null;

dtsPropsFor.MiniMap:
/** Track outline: centerline points in metres (y up), point count, closed loop or point-to-point, and bounding box. */ track: { xs: ArrayLike<number>;
ys: ArrayLike<number>;
n: number;
closed: boolean;
bounds: { minX: number;
maxX: number;
minY: number;
maxY: number } };
/** Size and stroke color via classes, e.g. "h-20 w-20 text-white/70". */ className?: string;

dtsPropsFor.SectorChip:
/** Zero-based sector index (rendered as "Sector index+1"). */ index: number;
/** Sector time in seconds;
null = sector not completed ("—"). */ time: number | null;
/** purple = best overall, green = personal best, yellow = slower, null = neutral grey. */ color: "purple" | "green" | "yellow" | null;
/** false = placeholder "··.···" (sector not reached yet). Default true. */ shown?: boolean;

dtsPropsFor.Stat:
label: string;
/** Pre-formatted value, e.g. "1:23.456". */ value: string;
/** Paint the value amber (records, highlights). */ accent?: boolean;

dtsPropsFor.WeatherBadge:
/** windToDeg = direction the wind blows towards, degrees counter-clockwise from east. */ conditions: { rain: boolean;
windKmh: number;
windToDeg: number };
/** "iso" = isometric race camera, "map" = north-up map. Default "iso". */ view?: "iso" | "map";

dtsPropsFor.WindArrow:
/** windToDeg = direction the wind blows towards, degrees counter-clockwise from east. */ conditions: { rain: boolean;
windKmh: number;
windToDeg: number };
view: "iso" | "map";
className?: string;
